// the lights follow the tap; a scene is kept; 'all off' turns everything off
const home = flow.get('home') || { ceiling: false, lamp: false, scene: 'day' };
const d = msg.data || {};
let toast = null;
if (msg.tile === 'ceiling' || msg.tile === 'lamp') home[msg.tile] = !!msg.value;
else if (msg.tile === 'scene') { home.scene = d.scene; if (d.scene === 'movie' || d.scene === 'night') { home.ceiling = false; home.lamp = d.scene === 'movie'; } }
else if (msg.tile === 'blinds') toast = { en: 'Blinds: ' + d.blinds, fr: 'Volets : ' + d.blinds, de: 'Rollläden: ' + d.blinds };
else if (msg.tile === 'all_off') { home.ceiling = false; home.lamp = false; home.scene = 'night'; toast = { en: 'Good night', fr: 'Bonne nuit', de: 'Gute Nacht' }; }
flow.set('home', home);
return [{ payload: { ceiling: home.ceiling, lamp: home.lamp, scene: home.scene } }, toast ? { payload: toast } : null];
